    # Compute length of Longest Increasing Subsequence
    if not arr:
        return 0
    tails = []
    for val in arr:
        # Binary search for the insertion point of val in tails
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < val:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(val)
        else:
            tails[lo] = val
    return len(tails)

